INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36597, 0, 0, 'So the Light\'s vaunted justice has finally arrived? Shall I lay down Frostmourne and throw myself at your mercy, Fordring?', 14, 0, 0, 0, 0, 17349, 'The Lich King - SAY_LK_INTRO_1'),
(36597, 1, 0, 'You\'ll learn of that first hand. When my work is complete, you will beg for mercy -- and I will deny you. Your anguished cries will be testament to my unbridled power...', 14, 0, 0, 22, 0, 17350, 'The Lich King - SAY_LK_INTRO_2'),
(36597, 2, 0, 'I\'ll keep you alive to witness the end, Fordring. I would not want the Light\'s greatest champion to miss seeing this wretched world remade in my image.', 14, 0, 0, 0, 0, 17351, 'The Lich King - SAY_LK_INTRO_3'),
(36597, 3, 0, 'Come then, champions. Feed me your rage!', 14, 0, 0, 0, 0, 0, 'The Lich King - SAY_LK_AGGRO'),
(36597, 4, 0, 'I will freeze you from within until all that remains is an icy husk.', 14, 0, 0, 0, 0, 17369, 'The Lich King - SAY_LK_REMORSELESS_WINTER'),
(36597, 5, 0, 'Watch as the world around you collapses!', 14, 0, 0, 0, 0, 17370, 'The Lich King - SAY_LK_QUAKE'),
(36597, 6, 0, 'Val\'kyr, your master calls!', 14, 0, 0, 0, 0, 17373, 'The Lich King - SAY_LK_SUMMON_VALKYR'),
(36597, 7, 0, 'Frostmourne hungers...', 14, 0, 0, 0, 0, 17366, 'The Lich King - SAY_LK_HARVEST_SOUL'),
(36597, 8, 0, 'Frostmourne, OBEY ME!', 14, 0, 0, 0, 0, 17367, 'The Lich King - SAY_LK_FROSTMOURNE_ESCAPE'),
(36597, 9, 0, 'Frostmourne feeds on the soul of your fallen ally!', 14, 0, 0, 0, 0, 17368, 'The Lich King - SAY_LK_FROSTMOURNE_KILL'),
(36597, 10, 0, 'Hope wanes...', 14, 0, 0, 0, 0, 17363, 'The Lich King - SAY_LK_KILL'),
(36597, 10, 1, 'The end has come!', 14, 0, 0, 0, 0, 17364, 'The Lich King - SAY_LK_KILL'),
(36597, 11, 0, 'Face now your tragic end.', 14, 0, 0, 0, 0, 17365, 'The Lich King - SAY_LK_BERSERK'),
(36597, 12, 0, '%s begins to cast Defile!', 41, 0, 0, 0, 0, 0, 'The Lich King - EMOTE_DEFILE_WARNING'),
(36597, 13, 0, ' |TInterface\\Icons\\ability_creature_disease_02.blp:16|t You have been infected by |cFFBC05FFNecrotic Plague|r! |TInterface\\Icons\\ability_creature_disease_02.blp:16|t', 42, 0, 0, 0, 0, 0, 'The Lich King - EMOTE_NECROTIC_PLAGUE_WARNING'),
(36597, 14, 0, 'No questions remain unanswered. No doubts linger. You ARE Azeroth\'s greatest champions. You overcame every challenge I laid before you. My mightiest servants have fallen before your relentless onslaught... your unbridled fury... ', 14, 0, 0, 0, 0, 17353, 'The Lich King - SAY_LK_OUTRO_1'),
(36597, 15, 0, 'Is it truly righteousness that drives you? I wonder...', 14, 0, 0, 0, 0, 17354, 'The Lich King - SAY_LK_OUTRO_2'),
(36597, 16, 0, 'You trained them well, Fordring. You delivered the greatest fighting force this world has ever known... right into my hands - exactly as I intended! You shall be rewarded for your unwitting sacrifice.', 14, 0, 0, 0, 0, 17355, 'The Lich King - SAY_LK_OUTRO_3'),
(36597, 17, 0, 'Watch now as I raise them from the dead to become masters of the Scourge. They will shroud this world in chaos and destruction. Azeroth\'s fall will come at their hands -- and you will be the first to die.', 14, 0, 0, 0, 0, 17356, 'The Lich King - SAY_LK_OUTRO_4'),
(36597, 18, 0, 'I delight in the irony.', 14, 0, 0, 0, 0, 17357, 'The Lich King - SAY_LK_OUTRO_5'),
(36597, 19, 0, 'Impossible...', 14, 0, 0, 0, 0, 17358, 'The Lich King - SAY_LK_OUTRO_6'),
(36597, 20, 0, 'Now I stand, the lion before the lambs... and they do not fear.', 14, 0, 0, 0, 0, 17361, 'The Lich King - SAY_LK_OUTRO_7'),
(36597, 21, 0, 'They cannot fear...', 14, 0, 0, 0, 0, 17362, 'The Lich King - SAY_LK_OUTRO_8');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36612, 0, 0, 'This is the beginning AND the end, mortals. None may enter the master\'s sanctum!', 14, 0, 0, 0, 0, 16950, 'Lord Marrowgar - SAY_ENTER_ZONE'),
(36612, 1, 0, 'The Scourge will wash over this world as a swarm of death and destruction!', 14, 0, 0, 0, 0, 16941, 'Lord Marrowgar - SAY_AGGRO'),
(36612, 2, 0, 'BONE STORM!', 14, 0, 0, 0, 0, 16946, 'Lord Marrowgar - SAY_BONE_STORM'),
(36612, 3, 0, 'Bound by bone!', 14, 0, 0, 0, 0, 16947, 'Lord Marrowgar - SAY_BONESPIKE_1'),
(36612, 3, 1, 'Stick around!', 14, 0, 0, 0, 0, 16948, 'Lord Marrowgar - SAY_BONESPIKE_2'),
(36612, 3, 2, 'The only escape is death!', 14, 0, 0, 0, 0, 16949, 'Lord Marrowgar - SAY_BONESPIKE_3'),
(36612, 4, 0, 'More bones for the offering!', 14, 0, 0, 0, 0, 16942, 'Lord Marrowgar - SAY_KILL_1'),
(36612, 4, 1, 'Languish in damnation!', 14, 0, 0, 0, 0, 16943, 'Lord Marrowgar - SAY_KILL_2'),
(36612, 5, 0, 'I see... Only darkness.', 14, 0, 0, 0, 0, 16944, 'Lord Marrowgar - SAY_DEATH'),
(36612, 6, 0, 'THE MASTER\'S RAGE COURSES THROUGH ME!', 14, 0, 0, 0, 0, 16945, 'Lord Marrowgar - SAY_BERSERK'),
(36612, 7, 0, '%s creates a whirling storm of bone!', 41, 0, 0, 0, 0, 0, 'Lord Marrowgar - SAY_BONE_STORM_EMOTE');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36626, 0, 0, 'No! You killed Stinky! You Pay!', 14, 0, 0, 0, 0, 16907, 'Festergut - SAY_STINKY_DEAD'),
(36626, 1, 0, 'Fun time?', 14, 0, 0, 0, 0, 16901, 'Festergut - SAY_AGGRO'),
(36626, 2, 0, '%s farts.', 16, 0, 0, 0, 0, 16911, 'Festergut - EMOTE_GAS_SPORE'),
(36626, 3, 0, '%s releases Gas Spores!', 41, 0, 0, 0, 0, 0, 'Festergut - EMOTE_WARN_GAS_SPORE'),
(36626, 4, 0, 'I not feel so good...', 14, 0, 0, 0, 0, 16906, 'Festergut - SAY_PUNGENT_BLIGHT'),
(36626, 5, 0, '%s begins to cast |cFFFF7F00Pungent Blight!|r', 41, 0, 0, 0, 0, 0, 'Festergut - EMOTE_WARN_PUNGENT_BLIGHT'),
(36626, 6, 0, '%s vomits.', 16, 0, 0, 0, 0, 0, 'Festergut - EMOTE_PUNGENT_BLIGHT'),
(36626, 7, 0, 'Daddy, I did it!', 14, 0, 0, 0, 0, 16902, 'Festergut - SAY_KILL_1'),
(36626, 7, 1, 'Dead, dead, dead!', 14, 0, 0, 0, 0, 16903, 'Festergut - SAY_KILL_2'),
(36626, 8, 0, 'Fun time over!', 14, 0, 0, 0, 0, 16905, 'Festergut - SAY_BERSERK'),
(36626, 9, 0, 'Da ... Ddy...', 14, 0, 0, 0, 0, 16904, 'Festergut - SAY_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36627, 0, 0, 'What? Precious? Noooooooooo!!!', 14, 0, 0, 0, 0, 16993, 'Rotface - SAY_PRECIOUS_DIES'),
(36627, 1, 0, 'Weeeeee!', 14, 0, 0, 0, 0, 16986, 'Rotface - SAY_AGGRO'),
(36627, 2, 0, '%s begins to cast Slime Spray!', 41, 0, 0, 0, 0, 0, 'Rotface - EMOTE_SLIME_SPRAY'),
(36627, 3, 0, 'Icky sticky!', 14, 0, 0, 0, 0, 16991, 'Rotface - SAY_SLIME_SPRAY'),
(36627, 4, 0, '|TInterface\\Icons\\spell_shadow_unstableaffliction_2.blp:16|t%s begins to cast |cFFFF0000Unstable Ooze Explosion!|r', 41, 0, 0, 0, 0, 0, 'Rotface - EMOTE_UNSTABLE_EXPLOSION'),
(36627, 5, 0, 'I tink I made an angry poo-poo. It gonna blow!', 14, 0, 0, 0, 0, 16992, 'Rotface - SAY_UNSTABLE_EXPLOSION'),
(36627, 6, 0, 'Daddy make new toys out of you!', 14, 0, 0, 0, 0, 16988, 'Rotface - SAY_KILL_1'),
(36627, 6, 1, 'I brokes-ded it...', 14, 0, 0, 0, 0, 16987, 'Rotface - SAY_KILL_2'),
(36627, 7, 0, 'SLEEPY TIME!', 14, 0, 0, 0, 0, 16990, 'Rotface - SAY_BERSERK'),
(36627, 8, 0, 'Bad news, daddy...', 14, 0, 0, 0, 0, 16989, 'Rotface - SAY_DEATH'),
(36627, 9, 0, '|TInterface\\Icons\\ability_creature_disease_02.blp:16|tYou have |cFF00FF00Mutated Infection!|r', 42, 0, 0, 0, 0, 0, 'Rotface - EMOTE_MUTATED_INFECTION');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36678, 0, 0, 'Just an ordinary gas cloud, but watch out because that\'s no ordinary gas cloud!', 14, 0, 0, 432, 0, 17119, 'Professor Putricide - SAY_GASEOUS_BLIGHT'),
(36678, 1, 0, 'Oh Festergut, you were always my favorite -- next to Rotface.  The good news is that you left behind so much gas. I can practically taste it!', 14, 0, 0, 0, 0, 17124, 'Professor Putricide - SAY_FESTERGUT_DEATH'),
(36678, 2, 0, 'Great news, everyone! The slime is flowing again!', 14, 0, 0, 1, 0, 17126, 'Professor Putricide - SAY_ROTFACE_OOZE_FLOOD1'),
(36678, 2, 1, 'Good news, everyone! I\'ve fixed the poison slime pipes!', 14, 0, 0, 1, 0, 17123, 'Professor Putricide - SAY_ROTFACE_OOZE_FLOOD2'),
(36678, 3, 0, 'Terrible news, everyone. Rotface is dead, but great news everyone! He left behind plenty of ooze for me to use! What? I\'m a poet and I didn\'t know it... Astounding!', 14, 0, 0, 0, 0, 17146, 'Professor Putricide - SAY_ROTFACE_DEATH'),
(36678, 4, 0, 'Good news, everyone! I think I\'ve perfected a plague that will destroy all life on Azeroth!', 14, 0, 0, 0, 0, 17114, 'Professor Putricide - SAY_AGGRO'),
(36678, 5, 0, '%s begins to cast Unstable Experiment!', 41, 0, 0, 0, 0, 0, 'Professor Putricide - EMOTE_UNSTABLE_EXPERIMENT'),
(36678, 6, 0, 'Two oozes, one room. So many delightful possibilities!', 14, 0, 0, 0, 0, 17122, 'Professor Putricide - SAY_PHASE_TRANSITION_HEROIC'),
(36678, 7, 0, 'Hrm, I don\'t feel a thing. Wha?! Where\'d those come from?', 14, 0, 0, 15, 0, 17120, 'Professor Putricide - SAY_TRANSFORM_1'),
(36678, 8, 0, 'Tastes like... Cherry! OH! Excuse me!', 14, 0, 0, 15, 0, 17121, 'Professor Putricide - SAY_TRANSFORM_2'),
(36678, 9, 0, '|TInterface\\Icons\\inv_misc_herb_evergreenmoss.blp:16|t%s cast |cFF00FF00Malleable Goo!|r', 41, 0, 0, 0, 0, 0, 'Professor Putricide - EMOTE_MALLEABLE_GOO'),
(36678, 10, 0, '%s cast |cFFFF7F00Choking Gas Bomb!|r', 41, 0, 0, 0, 0, 0, 'Professor Putricide - EMOTE_CHOKING_GAS_BOMB'),
(36678, 11, 0, 'Hrm, interesting...', 14, 0, 0, 0, 0, 17115, 'Professor Putricide - SAY_KILL_1'),
(36678, 11, 1, 'That was unexpected!', 14, 0, 0, 0, 0, 17116, 'Professor Putricide - SAY_KILL_2'),
(36678, 12, 0, 'Great news, everyone!', 14, 0, 0, 0, 0, 17118, 'Professor Putricide - SAY_BERSERK'),
(36678, 13, 0, 'Bad news, everyone... I don\'t think I\'m going to make it...', 14, 0, 0, 0, 0, 17117, 'Professor Putricide - SAY_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36789, 0, 0, 'Heroes, lend me your aid. I... I cannot hold them off much longer. You must heal my wounds!', 14, 0, 0, 0, 0, 17064, 'Valithria Dreamwalker - SAY_VALITHRIA_ENTER_COMBAT'),
(36789, 1, 0, 'I have opened a portal into the Dream. Your salvation lies within, heroes...', 14, 0, 0, 0, 0, 17068, 'Valithria Dreamwalker - SAY_VALITHRIA_DREAM_PORTAL'),
(36789, 2, 0, 'My strength is returning. Press on, heroes!', 14, 0, 0, 0, 0, 17070, 'Valithria Dreamwalker - SAY_VALITHRIA_75_PERCENT'),
(36789, 3, 0, 'I will not last much longer!', 14, 0, 0, 0, 0, 17069, 'Valithria Dreamwalker - SAY_VALITHRIA_25_PERCENT'),
(36789, 4, 0, 'Forgive me for what I do! I... cannot... stop... ONLY NIGHTMARES REMAIN!', 14, 0, 0, 0, 0, 17072, 'Valithria Dreamwalker - SAY_VALITHRIA_DEATH'),
(36789, 5, 0, 'A tragic loss...', 14, 0, 0, 0, 0, 17066, 'Valithria Dreamwalker - SAY_VALITHRIA_PLAYER_DEATH'),
(36789, 6, 0, 'FAILURES!', 14, 0, 0, 0, 0, 17067, 'Valithria Dreamwalker - SAY_VALITHRIA_BERSERK'),
(36789, 7, 0, 'I AM RENEWED! Ysera grant me the favor to lay these foul creatures to rest!', 14, 0, 0, 0, 0, 17071, 'Valithria Dreamwalker - SAY_VALITHRIA_SUCCESS');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36823, 0, 0, 'You have come to bring Arthas to justice? To see the Lich King destroyed?', 14, 0, 0, 0, 0, 17394, 'Terenas Menethil - SAY_TERENAS_INTRO_1'),
(36823, 1, 0, 'First, you must escape Frostmourne\'s hold, or be damned as I am; trapped within this cursed blade for all eternity. ', 14, 0, 0, 0, 0, 17395, 'Terenas Menethil - SAY_TERENAS_INTRO_2'),
(36823, 2, 0, 'Aid me in destroying these tortured souls! Together we will loosen Frostmourne\'s hold and weaken the Lich King from within!', 14, 0, 0, 0, 0, 17396, 'Terenas Menethil - SAY_TERENAS_INTRO_3');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36838, 0, 0, '|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t|cFFBC0000 OVERHEAT  |r|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t', 42, 0, 100, 0, 0, 0, 'Alliance Gunship Cannon - SAY_OVERHEAT');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36839, 0, 0, '|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t|cFFBC0000 OVERHEAT  |r|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t', 42, 0, 100, 0, 0, 0, 'Horde Gunship Cannon - SAY_OVERHEAT');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36853, 0, 0, 'You are fools to have come to this place. The icy winds of Northrend will consume your souls!', 14, 0, 0, 0, 0, 17007, 'Sindragosa - SAY_AGGRO'),
(36853, 1, 0, 'Suffer, mortals, as your pathetic magic betrays you!', 14, 0, 0, 0, 0, 17014, 'Sindragosa - SAY_UNCHAINED_MAGIC'),
(36853, 2, 0, '%s prepares to unleash a wave of blistering cold!', 41, 0, 0, 0, 0, 0, 'Sindragosa - EMOTE_WARN_BLISTERING_COLD'),
(36853, 3, 0, 'Can you feel the cold hand of death upon your heart?', 14, 0, 0, 0, 0, 17013, 'Sindragosa - SAY_BLISTERING_COLD'),
(36853, 4, 0, 'Aaagh! It burns! What sorcery is this!?', 14, 0, 0, 0, 0, 17015, 'Sindragosa - SAY_RESPITE_FOR_A_TORMENTED_SOUL'),
(36853, 5, 0, 'Your incursion ends here! None shall survive!', 14, 0, 0, 0, 0, 17012, 'Sindragosa - SAY_AIR_PHASE'),
(36853, 6, 0, 'Now, feel my master\'s limitless power and despair!', 14, 0, 0, 0, 0, 17016, 'Sindragosa - SAY_PHASE_2'),
(36853, 7, 0, '%s fires a frozen orb towards $n!', 41, 0, 0, 0, 0, 0, 'Sindragosa - EMOTE_WARN_FROZEN_ORB'),
(36853, 8, 0, 'Perish!', 14, 0, 0, 0, 0, 17008, 'Sindragosa - SAY_KILL 1'),
(36853, 8, 1, 'The flaw of mortality....', 14, 0, 0, 0, 0, 17009, 'Sindragosa - SAY_KILL 2'),
(36853, 9, 0, 'Enough! I tire of these games!', 14, 0, 0, 0, 0, 17011, 'Sindragosa - SAY_BERSERK'),
(36853, 10, 0, 'Free... at last....', 14, 0, 0, 0, 0, 17010, 'Sindragosa - SAY_DEATH'),
(36853, 11, 0, '%s goes into a berserker rage!', 41, 0, 100, 0, 0, 0, 'sindragosa EMOTE_BERSERK_RAID');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36855, 0, 0, 'You have found your way here, because you are among the few gifted with true vision in a world cursed with blindness.', 14, 0, 0, 0, 0, 17272, 'Lady Deathwhisper - SAY_INTRO_1'),
(36855, 1, 0, 'You can see through the fog that hangs over this world like a shroud, and grasp where true power lies.', 14, 0, 0, 0, 0, 17273, 'Lady Deathwhisper - SAY_INTRO_2'),
(36855, 2, 0, 'Fix your eyes upon your crude hands: the sinew, the soft meat, the dark blood coursing within.', 14, 0, 0, 0, 0, 16878, 'Lady Deathwhisper - SAY_INTRO_3'),
(36855, 3, 0, 'It is a weakness; a crippling flaw....  A joke played by the Creators upon their own creations.', 14, 0, 0, 0, 0, 17268, 'Lady Deathwhisper - SAY_INTRO_4'),
(36855, 4, 0, 'The sooner you come to accept your condition as a defect, the sooner you will find yourselves in a position to transcend it.', 14, 0, 0, 0, 0, 17269, 'Lady Deathwhisper - SAY_INTRO_5'),
(36855, 5, 0, 'Through our Master, all things are possible. His power is without limit, and his will unbending.', 14, 0, 0, 0, 0, 17270, 'Lady Deathwhisper - SAY_INTRO_6'),
(36855, 6, 0, 'Those who oppose him will be destroyed utterly, and those who serve -- who serve wholly, unquestioningly, with utter devotion of mind and soul -- elevated to heights beyond your ken.', 14, 0, 0, 0, 0, 17271, 'Lady Deathwhisper - SAY_INTRO_7'),
(36855, 7, 0, 'What is this disturbance? You dare trespass upon this hallowed ground? This shall be your final resting place!', 14, 0, 0, 0, 0, 16868, 'Lady Deathwhisper - SAY_AGGRO'),
(36855, 8, 0, 'Enough! I see I must take matters into my own hands!', 14, 0, 0, 0, 0, 16877, 'Lady Deathwhisper - SAY_PHASE_2'),
(36855, 9, 0, '%s\'s Mana Barrier shimmers and fades away!', 41, 0, 0, 0, 0, 0, 'Lady Deathwhisper - SAY_PHASE_2_EMOTE'),
(36855, 10, 0, 'You are weak, powerless to resist my will!', 14, 0, 0, 0, 0, 16876, 'Lady Deathwhisper - SAY_DOMINATE_MIND'),
(36855, 11, 0, 'Take this blessing and show these intruders a taste of the Master\'s power!', 14, 0, 0, 0, 0, 16873, 'Lady Deathwhisper - SAY_DARK_EMPOWERMENT'),
(36855, 12, 0, 'I release you from the curse of flesh!', 14, 0, 0, 0, 0, 16874, 'Lady Deathwhisper - SAY_DARK_TRANSFORMATION'),
(36855, 13, 0, 'Arise, and exult in your pure form!', 14, 0, 0, 0, 0, 16875, 'Lady Deathwhisper - SAY_ANIMATE_DEAD'),
(36855, 14, 0, 'Do you yet grasp the futility of your actions?', 14, 0, 0, 0, 0, 16869, 'Lady Deathwhisper - SAY_KILL_1'),
(36855, 14, 1, 'Embrace the darkness... darkness eternal.', 14, 0, 0, 0, 0, 16870, 'Lady Deathwhisper - SAY_KILL_2'),
(36855, 15, 0, 'This charade has gone on long enough!', 14, 0, 0, 0, 0, 16872, 'Lady Deathwhisper - SAY_BERSERK'),
(36855, 16, 0, 'All part of the Master\'s plan.... Your end is inevitable....', 14, 0, 0, 0, 0, 16871, 'Lady Deathwhisper - SAY_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36939, 0, 0, 'Rise up, sons and daughters of the Horde! Today we battle a hated enemy of the Horde! LOK\'TAR OGAR!', 14, 0, 100, 0, 0, 17087, 'High Overlord Saurfang - SAY_SAURFANG_INTRO_1'),
(36939, 1, 0, 'Kor\'kron, take us out!', 14, 0, 100, 0, 0, 17088, 'High Overlord Saurfang - SAY_SAURFANG_INTRO_2'),
(36939, 2, 0, 'What is that? Something approaching in the distance.', 14, 0, 100, 0, 0, 17089, 'High Overlord Saurfang - SAY_SAURFANG_INTRO_3'),
(36939, 3, 0, 'ALLIANCE GUNSHIP! ALL HANDS ON DECK!', 14, 0, 100, 0, 0, 17090, 'High Overlord Saurfang - SAY_SAURFANG_INTRO_4'),
(36939, 4, 0, 'You answer to Saurfang now!', 14, 0, 100, 0, 0, 17091, 'High Overlord Saurfang - SAY_SAURFANG_INTRO_5'),
(36939, 5, 0, 'You will know our business soon. Kor\'kron, ANNIHILATE THEM!', 14, 0, 100, 0, 0, 17092, 'High Overlord Saurfang - SAY_SAURFANG_INTRO_6'),
(36939, 6, 0, 'This is not your battle, dwarf. Back down or we will be forced to destroy your ship.', 14, 0, 100, 0, 0, 17083, 'High Overlord Saurfang - SAY_SAURFANG_INTRO_A'),
(36939, 7, 0, 'You DARE board my ship? Your death will come swiftly.', 14, 0, 100, 0, 0, 17083, 'High Overlord Saurfang - SAY_SAURFANG_BOARD'),
(36939, 8, 0, 'Reavers, Sergeants, attack!', 14, 0, 100, 0, 0, 17081, 'High Overlord Saurfang - SAY_SAURFANG_ENTER_SKYBREAKER'),
(36939, 9, 0, 'Axethrowers, hurl faster!', 14, 0, 100, 0, 0, 17079, 'High Overlord Saurfang - SAY_SAURFANG_AXETHROWERS'),
(36939, 10, 0, 'Rocketeers, reload!', 14, 0, 100, 0, 0, 17080, 'High Overlord Saurfang - SAY_SAURFANG_ROCKETEERS'),
(36939, 11, 0, 'We\'re taking hull damage, get a battle-mage out here to shut down those cannons!', 14, 0, 100, 0, 0, 17082, 'High Overlord Saurfang - SAY_SAURFANG_MAGES'),
(36939, 12, 0, 'The Alliance falter. Onward to the Lich King!', 14, 0, 100, 0, 0, 17084, 'High Overlord Saurfang - SAY_SAURFANG_VICTORY'),
(36939, 13, 0, 'Damage control! Put those fires out. You haven\'t seen the last of the Horde!', 14, 0, 100, 0, 0, 17085, 'High Overlord Saurfang - SAY_SAURFANG_WIPE');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(36948, 0, 0, 'Fire up the engines! We got a meetin\' with destiny, lads!', 14, 0, 100, 0, 0, 16962, 'Muradin Bronzebeard - SAY_MURADIN_INTRO_1'),
(36948, 1, 0, 'Hold on to yer hats!', 14, 0, 100, 0, 0, 16963, 'Muradin Bronzebeard - SAY_MURADIN_INTRO_2'),
(36948, 2, 0, 'What in the world is that? Grab me spyglass, crewman!', 14, 0, 100, 0, 0, 16964, 'Muradin Bronzebeard - SAY_MURADIN_INTRO_3'),
(36948, 3, 0, 'By me own beard! HORDE SAILIN\' IN FAST \'N HOT!', 14, 0, 100, 0, 0, 16965, 'Muradin Bronzebeard - SAY_MURADIN_INTRO_4'),
(36948, 4, 0, 'EVASIVE ACTION! MAN THE GUNS!', 14, 0, 100, 0, 0, 16966, 'Muradin Bronzebeard - SAY_MURADIN_INTRO_5'),
(36948, 5, 0, 'Cowardly dogs! Ye blindsided us!', 14, 0, 100, 0, 0, 16967, 'Muradin Bronzebeard - SAY_MURADIN_INTRO_6'),
(36948, 6, 0, 'Not me battle? I dunnae who ye think ye are, mister, but I got a score to settle with Arthas and yer not gettin\' in me way! FIRE ALL GUNS! FIRE! FIRE!', 14, 0, 100, 0, 0, 16968, 'Muradin Bronzebeard - SAY_MURADIN_INTRO_7'),
(36948, 7, 0, 'Move yer jalopy or we\'ll blow it out of the sky, orc! The Horde\'s got no business here.', 14, 0, 100, 0, 0, 16969, 'Muradin Bronzebeard - SAY_MURADIN_INTRO_H'),
(36948, 8, 0, 'What\'s this then?! Ye won\'t be takin\' this son o\' Ironforge\'s vessel without a fight!', 14, 0, 100, 0, 0, 16958, 'Muradin Bronzebeard - SAY_MURADIN_BOARD'),
(36948, 9, 0, 'Marines, Sergeants, attack!', 14, 0, 100, 0, 0, 16956, 'Muradin Bronzebeard - SAY_MURADIN_ENTER_ORGRIMMS_HAMMER'),
(36948, 10, 0, 'Riflemen, shoot faster!', 14, 0, 100, 0, 0, 16954, 'Muradin Bronzebeard - SAY_MURADIN_RIFLEMAN'),
(36948, 11, 0, 'Mortar team, reload!', 14, 0, 100, 0, 0, 16955, 'Muradin Bronzebeard - SAY_MURADIN_MORTAR'),
(36948, 12, 0, 'We\'re taking hull damage, get a sorcerer out here to shut down those cannons!', 14, 0, 100, 0, 0, 16957, 'Muradin Bronzebeard - SAY_MURADIN_SORCERERS'),
(36948, 13, 0, 'Don\'t say I didn\'t warn ya, scoundrels! Onward, brothers and sisters!', 14, 0, 100, 0, 0, 16959, 'Muradin Bronzebeard - SAY_MURADIN_VICTORY'),
(36948, 14, 0, 'Captain Bartlett, get us out of here! We\'re taken too much damage to stay afloat!', 14, 0, 100, 0, 0, 16960, 'Muradin Bronzebeard - SAY_MURADIN_WIPE');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37119, 0, 0, 'This is our final stand. What happens here will echo through the ages. Regardless of outcome, they will know that we fought with honor. That we fought for the freedom and safety of our people.$B$BRemember, hero, fear is your greatest enemy in these befouled halls. Steel your heart and your soul will shine brighter than a thousand suns. The enemy will falter at the sight of you. They will fall as the light of righteousness envelops them!', 14, 0, 0, 22, 0, 16653, 'Highlord Tirion Fordring - SAY_TIRION_INTRO_1'),
(37119, 1, 0, 'Remember, heroes, fear is your greatest enemy in these befouled halls. Steel your heart and your soul will shine brighter than a thousand suns. The enemy will falter at the sight of you. They will fall as the light of righteousness envelops them!', 14, 0, 0, 22, 0, 16654, 'Highlord Tirion Fordring - SAY_TIRION_INTRO_2'),
(37119, 2, 0, 'Our march upon Icecrown Citadel begins now!', 14, 0, 0, 22, 0, 16655, 'Highlord Tirion Fordring - SAY_TIRION_INTRO_3'),
(37119, 3, 0, 'ARTHAS! I swore that I would see you dead and the Scourge dismantled! I\'m going to finish what I started at Light\'s Hope!', 14, 0, 0, 22, 0, 16656, 'Highlord Tirion Fordring - SAY_TIRION_INTRO_4'),
(37119, 4, 0, 'The power of the Light knows no bounds, Saurfang. His soul is under great strain, but he lives - for now.', 12, 0, 0, 1, 0, 16658, 'Highlord Tirion Fordring - SAY_TIRION_INTRO_5'),
(37119, 5, 0, 'By the Light, it must be so!', 12, 0, 0, 5, 0, 16657, 'Highlord Tirion Fordring - SAY_TIRION_INTRO_A_5');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37120, 0, 0, 'So, it has begun....', 12, 0, 100, 396, 0, 16834, 'Highlord Darion Mograine to Player'),
(37120, 1, 0, 'Behold! The binding of sacred and corrupt; the forging of Shadow\'s Edge, a weapon of untold potential!', 12, 0, 100, 0, 0, 16835, 'Highlord Darion Mograine to Player'),
(37120, 2, 0, 'Bend it to your will, and you shall wield unspeakable power!', 12, 0, 100, 396, 0, 16836, 'Highlord Darion Mograine to Player'),
(37120, 3, 0, 'Fail, and your soul shall forever be its slave.', 12, 0, 100, 396, 0, 16837, 'Highlord Darion Mograine to Player'),
(37120, 4, 0, 'Father...', 12, 0, 100, 396, 0, 17411, 'Highlord Darion Mograine'),
(37120, 5, 0, 'Father. I feared for your... your sanity.', 12, 0, 100, 396, 0, 17412, 'Highlord Darion Mograine'),
(37120, 6, 0, 'Father... For you, I would give my life a thousand times.', 12, 0, 100, 396, 0, 17413, 'Highlord Darion Mograine');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37122, 0, 0, 'Never... could reach... the top shelf...', 14, 0, 0, 0, 0, 16586, 'Captain Arnath - SAY_ARNATH_DEATH'),
(37122, 1, 0, 'You miserable fools never did manage to select a decent bat wing.', 14, 0, 0, 0, 0, 16587, 'Captain Arnath - SAY_ARNATH_RESURRECTED'),
(37122, 2, 0, 'THAT was for bringing me spoiled spider ichor!\n', 14, 0, 0, 0, 0, 16588, 'Captain Arnath - SAY_ARNATH_KILL'),
(37122, 3, 0, 'Don\'t... let Finklestein use me... for his potions...', 14, 0, 0, 0, 0, 16589, 'Captain Arnath - SAY_ARNATH_SECOND_DEATH'),
(37122, 4, 0, 'The loss of our comrades was unpreventable. They lived and died in the service of the Argent Crusade.', 14, 0, 0, 0, 0, 16590, 'Captain Arnath - SAY_ARNATH_SURVIVE_TALK'),
(37122, 5, 0, 'Even dying here beats spending another day collecting reagents for that madman, Finklestein. ', 14, 0, 0, 0, 0, 16585, 'Captain Arnath - SAY_ARNATH_INTRO_2');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37123, 0, 0, 'No amount of healing can save me now. Fight on, brothers...', 14, 0, 0, 0, 0, 16810, 'Captain Brandon - SAY_BRANDON_DEATH'),
(37123, 1, 0, 'What? This strength...? All of the pain is gone! You... must join me in the eternal embrace of death!\n', 14, 0, 0, 0, 0, 16811, 'Captain Brandon - SAY_BRANDON_RESURRECTED'),
(37123, 2, 0, 'It doesn\'t hurt anymore, does it?\n', 14, 0, 0, 0, 0, 16812, 'Captain Brandon - SAY_BRANDON_KILL'),
(37123, 3, 0, 'I\'m sorry...', 14, 0, 0, 0, 0, 16813, 'Captain Brandon - SAY_BRANDON_SECOND_DEATH'),
(37123, 4, 0, 'You have done much in this war against the Scourge. May the light embrace you. ', 14, 0, 0, 0, 0, 16815, 'Captain Brandon - SAY_BRANDON_SURVIVE_TALK'),
(37123, 5, 0, 'By the light, the transporter worked!', 14, 0, 100, 0, 0, 16814, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37124, 0, 0, 'Please... burn my remains. Let me live warm in the afterlife...', 14, 0, 0, 0, 0, 16844, 'Captain Grondel - SAY_GRONDEL_DEATH'),
(37124, 1, 0, 'No! Why was I denied a death by flame? You must all BURN!  ', 14, 0, 0, 0, 0, 16845, 'Captain Grondel - SAY_GRONDEL_RESURRECTED'),
(37124, 2, 0, 'Can you feel the burn?', 14, 0, 0, 0, 0, 16846, 'Captain Grondel - SAY_GRONDEL_KILL'),
(37124, 3, 0, 'What... have I done? No!', 14, 0, 0, 0, 0, 16847, 'Captain Grondel - SAY_GRONDEL_SECOND_DEATH'),
(37124, 4, 0, 'What can possibly redeem this unholy place? Thank you.', 14, 0, 0, 0, 0, 16849, 'Captain Grondel - SAY_GRONDEL_SURVIVE_TALK');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37125, 0, 0, 'It was... a worthy afterlife.', 14, 0, 0, 0, 0, 16998, 'Captain Rupert - SAY_RUPERT_DEATH'),
(37125, 1, 0, 'There is no escaping the Lich King\'s will. Prepare for an explosive encounter!', 14, 0, 0, 0, 0, 16999, 'Captain Rupert - SAY_RUPERT_RESURRECTED'),
(37125, 2, 0, 'So that\'s what happens what you stand too close to a bomb!', 14, 0, 0, 0, 0, 17000, 'Captain Rupert - SAY_RUPERT_KILL'),
(37125, 3, 0, 'What an... explosive ending!', 14, 0, 0, 0, 0, 17001, 'Captain Rupert - SAY_RUPERT_SECOND_DEATH'),
(37125, 4, 0, 'Beware the dangers that lie ahead... and do try to remain in one piece. ', 14, 0, 0, 0, 0, 17003, 'Captain Rupert - SAY_RUPERT_SURVIVE_TALK');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37126, 0, 0, 'You may have once fought beside me, Crok, but now you are nothing more than a traitor. Come, your second death approaches!', 14, 0, 0, 0, 0, 17017, 'Sister Svalna - SAY_EVENT_START'),
(37126, 1, 0, 'Miserable creatures! Die! ', 14, 0, 0, 0, 0, 17018, 'Sister Svalna - SAY_KILL_CAPTAIN'),
(37126, 2, 0, 'Foolish Crok. You brought my reinforcements with you. Arise, Argent Champions, and serve the Lich King in death!', 14, 0, 0, 0, 0, 17019, 'Sister Svanlna - SAY_RESURRECT_CAPTAINS'),
(37126, 3, 0, 'Come, Scourgebane. I\'ll show the master which of us is truly worthy of the title of \"Champion\"!', 14, 0, 0, 0, 0, 17020, 'Sister Svalna - SAY_AGGRO'),
(37126, 4, 0, 'What a pitiful choice of an ally, Crok!', 14, 0, 0, 0, 0, 17021, 'Sister Svalna - SAY_KILL'),
(37126, 5, 0, 'They died so easily. No matter.', 14, 0, 0, 0, 0, 17022, 'Sister Svalna - SAY_CAPTAIN_DEATH'),
(37126, 6, 0, 'Perhaps... you were right, Crok. ', 14, 0, 0, 0, 0, 17023, 'Sister Svalna - SAY_DEATH'),
(37126, 7, 0, '%s has impaled $n!', 41, 0, 0, 0, 0, 0, 'Sister Svalna - EMOTE_SVALNA_IMPALE'),
(37126, 8, 0, '%s\'s Aether Shield has been shattered by $n!', 41, 0, 0, 0, 0, 0, 'Sister Svalna - EMOTE_SVALNA_BROKEN_SHIELD');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37129, 0, 0, 'Ready your arms, my Argent Brothers. The Vrykul will protect the Frost Queen with their lives.', 14, 0, 0, 0, 0, 16819, 'Crok Scourgebane - SAY_CROK_INTRO_1'),
(37129, 1, 0, 'Enough idle banter! Our champions have arrived - support them as we push our way through the hall!', 14, 0, 0, 0, 0, 16820, 'Crok Scourgebane - SAY_CROK_INTRO_3'),
(37129, 2, 0, 'Draw them back to us, and we\'ll assist you. ', 14, 0, 0, 0, 0, 16821, 'Crok Scourgebane - SAY_CROK_COMBAT_WP_0'),
(37129, 3, 0, 'Quickly, push on!', 14, 0, 0, 0, 0, 16823, 'Crok Scourgebane - SAY_CROK_COMBAT_WP_1'),
(37129, 4, 0, 'Her reinforcements will arrive shortly, we must bring her down quickly!', 14, 0, 0, 0, 0, 16824, 'Crok Scourgebane - SAY_CROK_FINAL_WP'),
(37129, 5, 0, 'I\'ll draw her attacks. Return our brothers to their graves, then help me bring her down!', 14, 0, 0, 15, 0, 16825, 'Crok Scourgebane - SAY_CROK_COMBAT_SVALNA'),
(37129, 6, 0, 'Augh! I must rest for a moment. \n', 14, 0, 0, 0, 0, 16826, 'Crok Scourgebane - SAY_CROK_WEAKENING_GAUNTLET'),
(37129, 7, 0, 'Champions! I cannot hold her back any longer.', 14, 0, 0, 0, 0, 16827, 'Crok Scourgebane - SAY_CROK_WEAKENING_SVALNA'),
(37129, 8, 0, 'Vengeance alone... was not enough!', 14, 0, 0, 0, 0, 16828, 'Crok Scourgebane - SAY_CROK_DEATH'),
(37129, 9, 0, 'I\'ll remain and inform Tirion of our progress. You must press on and bring down Sindragosa. Lok\'tar, champions! ', 14, 0, 100, 0, 0, 16830, ''),
(37129, 10, 0, 'Our champions have lost much blood in the struggle to activate this Scourge transporter. We must be prepared to return the favor. Follow me, men!', 14, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37184, 0, 0, 'Rocket Pack Active!', 15, 0, 100, 0, 0, 0, 'Zafod Boombox - SAY_ZAFOD_ROCKET_PACK_ACTIVE'),
(37184, 1, 0, 'Rocket Pack Disabled. Move closer to Zafod Boombox to re-activate.', 15, 0, 100, 0, 0, 0, 'Zafod Boombox - SAY_ZAFOD_ROCKET_PACK_DISABLED');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37187, 0, 0, 'Kor\'kron, move out! Champions, watch your backs. The Scourge have been...', 14, 0, 0, 22, 0, 17103, 'High Overlord Saurfang - SAY_INTRO_HORDE_1'),
(37187, 1, 0, 'My boy died at the Wrath Gate. I am here only to collect his body.', 12, 0, 0, 397, 0, 17097, 'High Overlord Saurfang - SAY_INTRO_HORDE_3'),
(37187, 2, 0, 'We named him Dranosh - It means \"Heart of Draenor\" in orcish. I would not let the warlocks take him. My boy would be safe, hidden away by the elders of Garadar.', 12, 0, 0, 1, 0, 17098, 'High Overlord Saurfang - SAY_INTRO_HORDE_5'),
(37187, 3, 0, 'I made a promise to his mother before she died; that I would cross the Dark Portal alone - whether I lived or died, my son would be safe. Untainted...', 12, 0, 0, 1, 0, 17099, 'High Overlord Saurfang - SAY_INTRO_HORDE_6'),
(37187, 4, 0, 'Today, I fulfill that promise.', 12, 0, 0, 397, 0, 17100, 'High Overlord Saurfang - SAY_INTRO_HORDE_7'),
(37187, 5, 0, '%s charges!', 16, 0, 0, 53, 0, 17104, 'High Overlord Saurfang - SAY_INTRO_HORDE_8'),
(37187, 6, 0, 'Behind you lies the body of my only son. Nothing will keep me from him. ', 12, 0, 0, 0, 0, 17094, 'High Overlord Saurfang - SAY_OUTRO_ALLIANCE_8'),
(37187, 7, 0, 'High Overlord Saurfang walks over to his son and kneels before his son\'s body.', 16, 0, 0, 0, 0, 0, 'High Overlord Saurfang - SAY_OUTRO_ALLIANCE_12'),
(37187, 8, 0, '[Orcish] No\'ku kil zil\'nok ha tar.', 12, 0, 0, 0, 0, 17096, 'High Overlord Saurfang - SAY_OUTRO_ALLIANCE_13'),
(37187, 9, 0, 'Higher Overlord Saurfang picks up the body of his son and walks over towards Varian', 16, 0, 0, 0, 0, 0, 'High Overlord Saurfang - SAY_OUTRO_ALLIANCE_14'),
(37187, 10, 0, 'I will not forget this... kindness. I thank you, Highness', 12, 0, 0, 0, 0, 17095, 'High Overlord Saurfang - SAY_OUTRO_ALLIANCE_15'),
(37187, 11, 0, '%s coughs.', 16, 0, 0, 0, 0, 17105, 'High Overlord Saurfang - SAY_OUTRO_HORDE_1'),
(37187, 12, 0, '%s weeps over the corpse of his son.', 16, 0, 0, 15, 0, 17106, 'High Overlord Saurfang - SAY_OUTRO_HORDE_2'),
(37187, 13, 0, 'You will have a proper ceremony in Nagrand, next to the pyres of your mother and ancestors.\n', 12, 0, 0, 0, 0, 17101, 'High Overlord Saurfang - SAY_OUTRO_HORDE_3'),
(37187, 14, 0, 'Honor, young heroes... no matter how dire the battle... never forsake it.', 12, 0, 0, 0, 0, 17102, 'High Overlord Saurfang - SAY_OUTRO_HORDE_4'),
(37187, 15, 0, 'The paladin still lives? Is it possible, Highlord? Could he have survived?', 12, 0, 0, 6, 0, 17107, 'High Overlord Saurfang - SAY_SAURFANG_INTRO_1'),
(37187, 16, 0, 'Then we must save him! If we rescue Bolvar Fordragon, we may quell the unrest between the Alliance and the Horde.', 12, 0, 0, 5, 0, 17108, 'High Overlord Saurfang - SAY_SAURFANG_INTRO_2'),
(37187, 17, 0, 'Our mission is now clear: The Lich King will answer for his crimes and we will save Highlord Bolvar Fordragon!', 12, 0, 0, 15, 0, 17109, 'High Overlord Saurfang - SAY_SAURFANG_INTRO_3'),
(37187, 18, 0, 'Kor\'kron, prepare Orgrim\'s Hammer for its final voyage! Champions, our gunship will find a point to dock on the upper reaches of the citadel. Meet us there!', 14, 0, 0, 22, 0, 17110, 'High Overlord Saurfang - SAY_SAURFANG_INTRO_4');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37200, 0, 0, 'Let\'s get a move on then! Move ou...', 14, 0, 0, 0, 0, 16974, 'Muradin Bronzebeard - SAY_INTRO_ALLIANCE_1'),
(37200, 1, 0, 'A lone orc against the might of the Alliance???', 14, 0, 0, 0, 0, 16970, 'Muradin Bronzebeard - SAY_INTRO_ALLIANCE_4'),
(37200, 2, 0, 'Charge!!!\n', 14, 0, 0, 0, 0, 16971, 'Muradin Bronzebeard - SAY_INTRO_ALLIANCE_5'),
(37200, 3, 0, '%s gasps for air.', 16, 0, 0, 0, 0, 16975, 'Muradin Bronzebeard - SAY_OUTRO_ALLIANCE_1'),
(37200, 4, 0, 'That was Saurfang\'s boy - the Horde commander at the Wrath Gate. Such a tragic end...', 12, 0, 0, 0, 0, 16976, 'Muradin Bronzebeard - SAY_OUTRO_ALLIANCE_2'),
(37200, 5, 0, 'What in the... There, in the distance!\n', 12, 0, 0, 0, 0, 16977, 'Muradin Bronzebeard - SAY_OUTRO_ALLIANCE_3'),
(37200, 6, 0, 'A Horde Zeppelin flies up to the rise.', 16, 0, 0, 0, 0, 0, 'Muradin Bronzebeard - SAY_OUTRO_ALLIANCE_4'),
(37200, 7, 0, 'Soldiers, fall in! Looks like the Horde are comin\' to take another shot!\n', 14, 0, 0, 0, 0, 16978, 'Muradin Bronzebeard - SAY_OUTRO_ALLIANCE_5'),
(37200, 8, 0, 'The Zeppelin docks, and High Overlord Saurfang hops out, confronting the Alliance soldiers and Muradin', 16, 0, 0, 0, 0, 0, 'Muradin Bronzebeard - SAY_OUTRO_ALLIANCE_6'),
(37200, 9, 0, 'Don\'t force me hand, orc. We can\'t let ye pass.', 12, 0, 0, 0, 0, 16972, 'Muradin Bronzebeard - SAY_OUTRO_ALLIANCE_7'),
(37200, 10, 0, 'I... I can\'t do it. Get back on yer ship and we\'ll spare yer life. ', 12, 0, 0, 0, 0, 16973, 'Muradin Bronzebeard - SAY_OUTRO_ALLIANCE_9'),
(37200, 11, 0, 'A mage portal from Stormwind appears between the two and Varian Wrynn and Jaina Proudmoore emerge.', 16, 0, 0, 0, 0, 0, 'Muradin Bronzebeard - SAY_OUTRO_ALLIANCE_10'),
(37200, 12, 0, 'Right away, yer majesty!', 12, 0, 0, 0, 0, 16979, 'Muradin Bronzebeard - SAY_OUTRO_ALLIANCE_21'),
(37200, 13, 0, 'Could it be, Lord Fordring? If Bolvar lives, mayhap there is hope fer peace between the Alliance and the Horde. We must reach the top o\' this cursed place and free the paladin!', 12, 0, 0, 6, 0, 16980, 'Muradin Bronzebeard - SAY_SAURFANG_INTRO_2'),
(37200, 14, 0, 'Prepare the Skybreaker fer an aerial assault on the citadel!', 14, 0, 0, 5, 0, 16981, 'Muradin Bronzebeard - SAY_SAURFANG_INTRO_3'),
(37200, 15, 0, 'Heroes, ye must fight yer way to a clear extraction point within Icecrown. We\'ll try an\' rendezvous on the ramparts!', 14, 0, 0, 22, 0, 16982, 'Muradin Bronzebeard - SAY_SAURFANG_INTRO_4');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37230, 0, 0, 'A screeching cry pierces the air above!', 41, 0, 100, 0, 0, 0, 'Spire Frostwyrm to Player');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37503, 0, 0, 'You must not approach the Frost Queen. Quickly, stop them!', 14, 0, 100, 0, 0, 17167, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37813, 0, 0, 'For every Horde soldier that you killed -- for every Alliance dog that fell, the Lich King\'s armies grew. Even now the val\'kyr work to raise your fallen as Scourge.\n', 14, 0, 0, 0, 0, 16701, 'Deathbringer Saurfang - SAY_INTRO_ALLIANCE_2'),
(37813, 1, 0, 'Things are about to get much worse. Come, taste the power that the Lich King has bestowed upon me!', 14, 0, 0, 0, 0, 16702, 'Deathbringer Saurfang - SAY_INTRO_ALLIANCE_3'),
(37813, 2, 0, 'Dwarves...', 14, 0, 0, 0, 0, 16703, 'Deathbringer Saurfang - SAY_INTRO_ALLIANCE_6'),
(37813, 3, 0, '%s immobilizes Muradin and his guards.', 16, 0, 0, 0, 0, 0, 'Deathbringer Saurfang - SAY_INTRO_ALLIANCE_7'),
(37813, 4, 0, 'Join me, father. Join me and we will crush this world in the name of the Scourge -- for the glory of the Lich King!', 14, 0, 0, 0, 0, 16704, 'Deathbringer Saurfang - SAY_INTRO_HORDE_2'),
(37813, 5, 0, 'Stubborn and old. What chance do you have? I am stronger, and more powerful than you ever were.', 14, 0, 0, 5, 0, 16705, 'Deathbringer Saurfang - SAY_INTRO_HORDE_4'),
(37813, 6, 0, 'Pathetic old orc! Come then, heroes. Come and face the might of the Scourge!', 14, 0, 0, 15, 0, 16706, 'Deathbringer Saurfang - SAY_INTRO_HORDE_9'),
(37813, 7, 0, 'BY THE MIGHT OF THE LICH KING!', 14, 0, 0, 0, 0, 16694, 'Deathbringer Saurfang - SAY_AGGRO'),
(37813, 8, 0, 'The ground runs red with your blood!', 14, 0, 0, 0, 0, 16699, 'Deathbringer Saurfang - SAY_MARK_OF_THE_FALLEN_CHAMPION'),
(37813, 9, 0, 'Feast, my minions!', 14, 0, 0, 0, 0, 16700, 'Deathbringer Saurfang - SAY_BLOOD_BEASTS'),
(37813, 10, 0, 'You are nothing!', 14, 0, 0, 0, 0, 16695, 'Deathbringer Saurfang - SAY_KILL_1'),
(37813, 10, 1, 'Your soul will find no redemption here!', 14, 0, 0, 0, 0, 16696, 'Deathbringer Saurfang - SAY_KILL_2'),
(37813, 11, 0, '%s goes into a frenzy!', 41, 0, 0, 0, 0, 0, 'Deathbringer Saurfang - SAY_FRENZY'),
(37813, 12, 0, 'I have become... DEATH!', 14, 0, 0, 0, 0, 16698, 'Deathbringer Saurfang - SAY_BERSERK'),
(37813, 13, 0, 'I... Am... Released...', 14, 0, 0, 0, 0, 16697, 'Deathbringer Saurfang - SAY_DEATH'),
(37813, 14, 0, '%s\'s Blood Beasts gain the scent of blood!', 41, 0, 0, 0, 0, 0, 'Deathbringer Saurfang - EMOTE_SCENT_OF_BLOOD');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37955, 0, 0, 'You have made an... unwise... decision.', 14, 0, 0, 0, 0, 16782, 'Blood-Queen Lana\'thel - SAY_AGGRO'),
(37955, 1, 0, 'Just a taste...', 14, 0, 0, 0, 0, 16783, 'Blood-Queen Lana\'thel - SAY_VAMPIRIC_BITE'),
(37955, 1, 1, 'Know my hunger!', 14, 0, 0, 0, 0, 16784, 'Blood-Queen Lana\'thel - SAY_VAMPIRIC_BITE'),
(37955, 2, 0, 'Yes! Feed, my precious one! You are mine now!', 14, 0, 0, 0, 0, 16790, 'Blood-Queen Lana\'thel - SAY_MIND_CONTROL'),
(37955, 3, 0, 'You thirst for blood!', 42, 0, 0, 0, 0, 0, 'Blood-Queen Lana\'thel - EMOTE_BLOODTHIRST'),
(37955, 4, 0, 'SUFFER!', 14, 0, 75, 0, 0, 16786, 'Blood-Queen Lana\'thel - SAY_SWARMING_SHADOWS'),
(37955, 5, 0, 'Shadows amass and swarm around $n!', 41, 0, 0, 0, 0, 0, 'Blood-Queen Lana\'thel - EMOTE_SWARMING_SHADOWS'),
(37955, 6, 0, 'Can you handle this?', 14, 0, 75, 0, 0, 16787, 'Blood-Queen Lana\'thel - SAY_PACT_OF_THE_DARKFALLEN'),
(37955, 7, 0, 'Here it comes...', 14, 0, 0, 0, 0, 16788, 'Blood-Queen Lana\'thel - SAY_AIR_PHASE'),
(37955, 8, 0, 'Really...? Is that all you\'ve got?', 14, 0, 0, 0, 0, 16791, 'Blood-Queen Lana\'thel - SAY_KILL'),
(37955, 8, 1, 'Such a pity.', 14, 0, 0, 0, 0, 16792, 'Blood-Queen Lana\'thel - SAY_KILL'),
(37955, 9, 0, 'How... unfortunate.', 14, 0, 0, 0, 0, 16789, 'Blood-Queen Lana\'thel - SAY_WIPE'),
(37955, 10, 0, 'This ends NOW!', 14, 0, 0, 0, 0, 16793, 'Blood-Queen Lana\'thel - SAY_BERSERK'),
(37955, 11, 0, 'But... we were getting along... so... well...', 14, 0, 0, 0, 0, 16794, 'Blood-Queen Lana\'thel - SAY_DEATH'),
(37955, 12, 0, '%s goes into a berserker rage!', 41, 0, 100, 0, 0, 0, 'blood queen lana thel EMOTE_BERSERK_RAID');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37970, 0, 0, 'Naxxanar was merely a setback! With the power of the orb, Valanar will have his vengeance!', 14, 0, 0, 0, 0, 16685, 'Prince Valanar - SAY_VALANAR_INVOCATION'),
(37970, 1, 0, 'Invocation of Blood jumps to Prince Valanar!', 41, 0, 0, 0, 0, 0, 'Prince Valanar - EMOTE_VALANAR_INVOCATION'),
(37970, 2, 0, 'My cup runneth over.', 14, 0, 0, 0, 0, 16686, 'Prince Valanar - SAY_VALANAR_SPECIAL'),
(37970, 3, 0, '%s begins casting Empowered Shock Vortex!', 41, 0, 0, 0, 0, 0, 'Prince Valanar - EMOTE_VALANAR_SHOCK_VORTEX'),
(37970, 4, 0, 'Dinner... is served.', 14, 0, 0, 0, 0, 16681, 'Prince Valanar - SAY_VALANAR_KILL_1'),
(37970, 4, 1, 'Do you see NOW the power of the Darkfallen?', 14, 0, 0, 0, 0, 16682, 'Prince Valanar - SAY_VALANAR_KILL_2'),
(37970, 5, 0, 'BOW DOWN BEFORE THE SAN\'LAYN!', 14, 0, 0, 0, 0, 16684, 'Prince Valanar - SAY_VALANAR_BERSERK'),
(37970, 6, 0, '...why...?', 14, 0, 0, 0, 0, 16683, 'Prince Valanar - SAY_VALANAR_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37972, 0, 0, 'Such wondrous power! The Darkfallen Orb has made me INVINCIBLE!', 14, 0, 0, 0, 0, 16727, 'Prince Keleseth - SAY_KELESETH_INVOCATION'),
(37972, 1, 0, 'Invocation of Blood jumps to Prince Keleseth!', 41, 0, 0, 0, 0, 0, 'Prince Keleseth - EMOTE_KELESETH_INVOCATION'),
(37972, 2, 0, 'Blood will flow.', 14, 0, 0, 0, 0, 16728, 'Prince Keleseth - SAY_KELESETH_SPECIAL'),
(37972, 3, 0, 'Were you ever a threat?', 14, 0, 0, 0, 0, 16723, 'Prince Keleseth - SAY_KELESETH_KILL_1'),
(37972, 3, 1, 'Truth is found in death.', 14, 0, 0, 0, 0, 16724, 'Prince Keleseth - SAY_KELESETH_KILL_2'),
(37972, 4, 0, '%s cackles maniacally.\n', 16, 0, 0, 0, 0, 16726, 'Prince Keleseth - EMOTE_KELESETH_BERSERK'),
(37972, 5, 0, 'My queen, they... come.', 14, 0, 0, 0, 0, 16725, 'Prince Keleseth - SAY_KELESETH_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(37973, 0, 0, 'Tremble before Taldaram, mortals, for the power of the orb flows through me!', 14, 0, 0, 0, 0, 16857, 'Prince Taldaram - SAY_TALDARAM_INVOCATION'),
(37973, 1, 0, 'Invocation of Blood jumps to Prince Taldaram!', 41, 0, 0, 0, 0, 0, 'Prince Taldaram - EMOTE_TALDARAM_INVOCATION'),
(37973, 2, 0, 'Delight in the pain!', 14, 0, 0, 0, 0, 16858, 'Prince Taldaram - SAY_TALDARAM_SPECIAL'),
(37973, 3, 0, 'Empowered Flames speed toward $n!', 41, 0, 0, 0, 0, 0, 'Prince Taldaram - EMOTE_TALDARAM_FLAME'),
(37973, 4, 0, 'Worm food.', 14, 0, 0, 0, 0, 16853, 'Prince Taldaram - SAY_TALDARAM_KILL_1'),
(37973, 4, 1, 'Beg for mercy!', 14, 0, 0, 0, 0, 16854, 'Prince Taldaram - SAY_TALDARAM_KILL_2'),
(37973, 5, 0, '%s laughs.', 16, 0, 0, 0, 0, 16856, 'Prince Taldaram - EMOTE_TALDARAM_BERSERK'),
(37973, 6, 0, '%s gurgles and dies.', 16, 0, 0, 0, 0, 16855, 'Prince Taldaram - EMOTE_TALDARAM_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(38004, 0, 0, 'Foolish mortals. You thought us defeated so easily? The San\'layn are the Lich King\'s immortal soldiers! Now you shall face their might combined!', 14, 0, 0, 1, 0, 16795, 'Blood-Queen Lana\'thel - SAY_INTRO_1'),
(38004, 1, 0, 'Rise up, brothers, and destroy our enemies!', 14, 0, 0, 0, 0, 16796, 'Blood-Queen Lana\'thel - SAY_INTRO_2');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(38472, 0, 0, 'Die, intruders! None shall interfere with the Cult\'s plans!', 14, 0, 0, 0, 0, 0, 'Darnavan - SAY_DARNAVAN_AGGRO'),
(38472, 1, 0, 'Wh- where am I...?  What a nightmare I have had....  But this is no time to reflect, I have much information to report!', 12, 0, 0, 0, 0, 0, 'Darnavan - SAY_DARNAVAN_RESCUED');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(38485, 0, 0, 'Die, intruders! None shall interfere with the Cult\'s plans!', 14, 0, 0, 0, 0, 0, 'Darnavan - SAY_DARNAVAN_AGGRO'),
(38485, 1, 0, 'Wh- where am I...?  What a nightmare I have had....  But this is no time to reflect, I have much information to report!', 12, 0, 0, 0, 0, 0, 'Darnavan - SAY_DARNAVAN_RESCUED');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(38606, 0, 0, 'What\'s this!?', 12, 0, 100, 5, 0, 17383, 'Lady Jaina Proudmoore to Player'),
(38606, 1, 0, 'He... he kept it? All this time, he kept it!?', 12, 0, 100, 5, 0, 17384, 'Lady Jaina Proudmoore'),
(38606, 2, 0, 'I knew! ', 12, 0, 100, 5, 0, 17385, 'Lady Jaina Proudmoore'),
(38606, 3, 0, 'I sensed a part of him still alive! Trapped... struggling... Oh, Arthas!', 12, 0, 100, 396, 0, 17386, 'Lady Jaina Proudmoore'),
(38606, 4, 0, 'Perhaps - perhaps he might someday remember what he once was.', 12, 0, 100, 396, 0, 17387, 'Lady Jaina Proudmoore'),
(38606, 5, 0, 'By the Light, may he at last find rest, free from the icy grip of that terrible blade.', 12, 0, 100, 396, 0, 17388, 'Lady Jaina Proudmoore');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(38607, 0, 0, 'Oh, lad...', 12, 0, 100, 396, 0, 17421, 'Muradin Bronzebeard'),
(38607, 1, 0, 'How I miss those endless days in Lordaeron...', 12, 0, 100, 396, 0, 17422, 'Muradin Bronzebeard'),
(38607, 2, 0, '...sharpenin\' yer skill with this dull blade...', 12, 0, 100, 396, 0, 17423, 'Muradin Bronzebeard'),
(38607, 3, 0, '...forgin\' ya into a weapon meant to withstand the demands of a great destiny.', 12, 0, 100, 396, 0, 17424, 'Muradin Bronzebeard'),
(38607, 4, 0, 'Heh... Yeh sure put them skills ta use, didn\'t yeh, lad?', 12, 0, 100, 6, 0, 17425, 'Muradin Bronzebeard'),
(38607, 5, 0, 'If only I\'da been able ta stop yeh that day, how different things mighta been.', 12, 0, 100, 396, 0, 17426, 'Muradin Bronzebeard'),
(38607, 6, 0, 'If only I\'da never discovered that accursed blade...', 12, 0, 100, 396, 0, 17427, 'Muradin Bronzebeard'),
(38607, 7, 0, 'Farewell, Arthas... my brother.', 12, 0, 100, 396, 0, 17428, 'Muradin Bronzebeard');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(38608, 0, 0, 'Arthas...', 12, 0, 100, 396, 0, 17402, 'Uther the Lightbringer'),
(38608, 1, 0, 'Alas, hero of Azeroth, you give me a greater gift than you know.', 12, 0, 100, 396, 0, 17403, 'Uther the Lightbringer'),
(38608, 2, 0, 'Long have I struggled to forgive the prince for his terrible transgressions.', 12, 0, 100, 396, 0, 17404, 'Uther the Lightbringer'),
(38608, 3, 0, 'My soul has been wracked with unbearable anxiety, dark thoughts... distancing me from the Light.', 12, 0, 100, 396, 0, 17405, 'Uther the Lightbringer'),
(38608, 4, 0, 'I recall clearly the gleam of pride in his eye as he stood before me, eager to defeat the enemies of the Light...', 12, 0, 100, 396, 0, 17406, 'Uther the Lightbringer'),
(38608, 5, 0, 'Eager to defend his people, no matter the cost.', 12, 0, 100, 396, 0, 17407, 'Uther the Lightbringer'),
(38608, 6, 0, 'It is this memory of Arthas that I choose to keep in my heart.', 12, 0, 100, 396, 0, 17408, 'Uther the Lightbringer'),
(38608, 7, 0, 'I shall always be in your debt, friend.', 12, 0, 100, 396, 0, 17409, 'Uther the Lightbringer'),
(38608, 8, 0, 'Thank you.', 12, 0, 100, 0, 0, 17410, 'Uther the Lightbringer');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(38609, 0, 0, 'So, it is done.', 12, 0, 100, 396, 0, 17376, 'Lady Sylvanas Windrunner'),
(38609, 1, 0, 'I had not dared to trust my senses - too many times has the Lich King made me to be a fool.', 12, 0, 100, 396, 0, 17377, 'Lady Sylvanas Windrunner'),
(38609, 2, 0, 'Finally, he has been made to pay for the atrocities he imposed upon my people.', 12, 0, 100, 396, 0, 17378, 'Lady Sylvanas Windrunner'),
(38609, 3, 0, 'May Azeroth never fail to remember the terrible price we paid for our weakness... for our pride.', 12, 0, 100, 396, 0, 17379, 'Lady Sylvanas Windrunner'),
(38609, 4, 0, 'But what now, hero? What of those freed from his grasp, but still shackled to their mortal coils?', 12, 0, 100, 6, 0, 17380, 'Lady Sylvanas Windrunner'),
(38609, 5, 0, 'Leave me. ', 12, 0, 100, 396, 0, 17381, 'Lady Sylvanas Windrunner'),
(38609, 6, 0, 'I have much to ponder.', 12, 0, 100, 396, 0, 17382, 'Lady Sylvanas Windrunner');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(38995, 0, 0, 'We\'ll grant you a swift death, Arthas. More than can be said for the thousands you\'ve tortured and slain.', 14, 0, 0, 0, 0, 17390, 'Highlord Tirion Fordring - SAY_TIRION_INTRO_1'),
(38995, 1, 0, 'So be it. Champions, attack!', 14, 0, 0, 0, 0, 17391, 'Highlord Tirion Fordring - SAY_TIRION_INTRO_2'),
(38995, 2, 0, 'LIGHT GRANT ME ONE FINAL BLESSING! GIVE ME THE STRENGTH... TO SHATTER THESE BONDS!', 14, 0, 0, 0, 0, 17392, 'Highlord Tirion Fordring - SAY_TIRION_OUTRO_1'),
(38995, 3, 0, 'No more, Arthas! No more lives will be consumed by your hatred!', 14, 0, 0, 0, 0, 17393, 'Highlord Tirion Fordring - SAY_TIRION_OUTRO_2');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(39217, 0, 0, 'You have come to bring Arthas to justice? To see the Lich King destroyed?', 14, 0, 0, 0, 0, 17394, 'Terenas Menethil - SAY_TERENAS_INTRO_1'),
(39217, 1, 0, 'First, you must escape Frostmourne\'s hold, or be damned as I am; trapped within this cursed blade for all eternity. ', 14, 0, 0, 0, 0, 17395, 'Terenas Menethil - SAY_TERENAS_INTRO_2');
